out_grid = demo1["output"]

# Let me look at the c%3, r_idx (NOT r%3) mapping more carefully
# and identify which cells change

print("Detailed view by (c%3, r_idx):")

crs = [0, 3, 6, 9]
ccs = [0, 3, 6, 9, 12]

