    for cc in ccs:
        inp = [in_grid[cr+j][cc+k] for j in [0,1] for k in [0,1]]
        out = [out_grid[cr+j][cc+k] for j in [0,1] for k in [0,1]]
        c_mod3 = cc % 3
        r_idx = cr // 3

        key = (c_mod3, r_idx)

        if inp != out:
            if key not in changes_by_pos:
                changes_by_pos[key] = []
            changes_by_pos[key].append((list(inp), list(out)))

